+// DSH Web 端口自动发现。
+//
+// 为什么需要：DSH 桌面版每次启动都由 Electron 挑一个**随机空闲端口**（57275 / 59820 /
+// 62844 … 都见过），而 qq-bridge 的 `config.json` 里 `dsh.baseUrl` 是写死的。
+// DSH 一重启端口就变，桥接随即 401/ECONNREFUSED，QQ 侧表现为「收到消息但不回」，
+// 而日志里只有一条 DSH 不可用 —— 这个坑已经踩过两次，所以做成自动的。
+//
+// 发现顺序（先快后慢，任一条通过**鉴权校验**就采用）：
+//   1. 环境变量 DSH_WEB_URL（从 DSH 内部启动的进程会有；Explorer 启动的没有）
+//   2. config.json 里现有的 baseUrl（没变就直接用，零成本）
+//   3. netstat 里监听 127.0.0.1、且进程名像 DSH/Electron 的端口
+//   4. 老版本的默认端口 3080
+//
+// 校验方式不是「端口能连上」——那太容易误判（别的本地服务也会应 200）。
+// 而是用 `~/.dsh/.credentials.yaml` 里持久化的签名密钥，为**该 authority** 铸造
+// 会话 Cookie，再打一次 `settings/describe`：Cookie 名称与签名载荷都绑定了
+// host:port，能返回 ok:true 就证明「这个端口确实是 DSH，而且密钥匹配」。
+import fs from 'node:fs';
+import path from 'node:path';
+import { spawnSync } from 'node:child_process';
+import { discoverDshSessionCookie, isLoopbackBase } from './dsh-client.js';
+
+/** DSH 桌面版的进程名特征（Electron 打包后通常是 "DeepSeek Harness.exe"）。 */
+const DSH_PROCESS_HINT = /deepseek|dsh/i;
+
+/** 单个候选的校验超时：本机回环，2 秒足够。 */
+const PROBE_TIMEOUT_MS = 2000;
+
+/**
+ * 从 `netstat -ano` + `tasklist` 里找出「像 DSH 的进程」正在监听的端口。
+ * 纯系统命令，不需要管理员权限。
+ * @returns {number[]} 去重后的端口数组（按端口升序）
+ */
+export function dshCandidatePortsFromProcesses() {
+  if (process.platform !== 'win32') return [];
+  const ports = new Set();
+  try {
+    const net = spawnSync('netstat', ['-ano', '-p', 'tcp'], { encoding: 'utf8', timeout: 6000, windowsHide: true });
+    if (net.error || net.status !== 0) return [];
+    const listeners = new Map(); // pid -> port[]
+    for (const raw of String(net.stdout ?? '').split(/\r?\n/)) {
+      const line = raw.trim();
+      if (!line || !/^TCP\b/i.test(line)) continue;
+      const f = line.split(/\s+/);
+      if (f.length < 5 || !/^LISTENING$/i.test(f[3])) continue;
+      const local = f[1];
+      const idx = local.lastIndexOf(':');
+      if (idx <= 0) continue;
+      const host = local.slice(0, idx).replace(/^\[|\]$/g, '');
+      const port = Number(local.slice(idx + 1));
+      if (!Number.isInteger(port) || port <= 0 || port > 65535) continue;
+      // 只认回环/全地址监听（DSH 不会只在某个外网网卡上监听）
+      if (!['127.0.0.1', '0.0.0.0', '::1', '::'].includes(host)) continue;
+      const pid = Number(f[4]);
+      if (!Number.isInteger(pid) || pid <= 0) continue;
+      if (!listeners.has(pid)) listeners.set(pid, []);
+      listeners.get(pid).push(port);
+    }
+    if (listeners.size === 0) return [];
+    // 一次拿全部进程名，避免每个 PID 起一个 tasklist
+    const tl = spawnSync('tasklist', ['/FO', 'CSV', '/NH'], { encoding: 'utf8', timeout: 8000, windowsHide: true });
+    if (tl.error || tl.status !== 0) return [];
+    const nameByPid = new Map();
+    for (const raw of String(tl.stdout ?? '').split(/\r?\n/)) {
+      const line = raw.trim();
+      if (!line.startsWith('"')) continue;
+      const cols = line.split('","').map((c) => c.replace(/^"|"$/g, ''));
+      if (cols.length < 2) continue;
+      const name = cols[0];
+      const pid = Number(cols[1]);
+      if (Number.isInteger(pid)) nameByPid.set(pid, name);
+    }
+    for (const [pid, list] of listeners) {
+      const name = nameByPid.get(pid) ?? '';
+      if (!DSH_PROCESS_HINT.test(name)) continue;
+      for (const p of list) ports.add(p);
+    }
+  } catch {
+    return [];
+  }
+  return [...ports].sort((a, b) => a - b);
+}
+
+/**
+ * 该地址是否真的是 DSH（用铸造 Cookie 打一次只读 RPC 验证）。
+ * @param {string} baseUrl - 形如 http://127.0.0.1:62844
+ * @returns {Promise<boolean>}
+ */
+export async function probeDshBaseUrl(baseUrl) {
+  if (!baseUrl || !isLoopbackBase(baseUrl)) return false;
+  let cookie;
+  try {
+    cookie = discoverDshSessionCookie(baseUrl);
+  } catch {
+    return false;
+  }
+  if (!cookie) return false;
+  const controller = new AbortController();
+  const timer = setTimeout(() => controller.abort(), PROBE_TIMEOUT_MS);
+  try {
+    const res = await fetch(`${baseUrl}/api/settings/describe`, {
+      method: 'POST',
+      headers: { cookie, 'content-type': 'application/json' },
+      body: JSON.stringify({
+        type: 'client-request',
+        rpcId: 'discover-' + Math.random().toString(36).slice(2, 8),
+        method: 'settings/describe',
+        payload: { args: {} },
+      }),
+      signal: controller.signal,
+    });
+    if (!res.ok) return false;
+    const body = await res.json().catch(() => null);
+    // 必须拿到 result.ok===true：401/404/别的服务返回的 200 都会被这一条挡掉。
+    return body?.result?.ok === true;
+  } catch {
+    return false;
+  } finally {
+    clearTimeout(timer);
+  }
+}
+
+/**
+ * 组装候选地址列表（去重、保序）。
+ * @param {string} currentBaseUrl - config.json 里现有的 baseUrl
+ * @returns {string[]}
+ */
+export function candidateDshBaseUrls(currentBaseUrl) {
+  const out = [];
+  const push = (url) => {
+    const v = String(url ?? '').trim().replace(/\/+$/, '');
+    if (!v || out.includes(v)) return;
+    if (!/^https?:\/\//i.test(v)) return;
+    out.push(v);
+  };
+  push(process.env.DSH_WEB_URL);
+  push(currentBaseUrl);
+  for (const port of dshCandidatePortsFromProcesses()) push(`http://127.0.0.1:${port}`);
+  push('http://127.0.0.1:3080');
+  return out;
+}
+
+/**
+ * 依次校验候选地址，返回第一个真正可用的 DSH 基址。
+ * @param options.currentBaseUrl - 现有配置（优先级最高，命中即零成本返回）
+ * @param options.log - 可选日志函数
+ * @returns {Promise<string|null>} 可用基址；全都不通时返回 null
+ */
+export async function discoverDshBaseUrl({ currentBaseUrl, log = () => {} } = {}) {
+  const candidates = candidateDshBaseUrls(currentBaseUrl);
+  for (const [i, url] of candidates.entries()) {
+    const ok = await probeDshBaseUrl(url);
+    if (ok) {
+      if (i > 0) log(`🔎 DSH 端口已自动发现：${url}（试探 ${i + 1} 个候选）`);
+      return url;
+    }
+  }
+  log('⚠️ DSH 端口自动发现失败：所有候选都未通过鉴权校验（DSH 是否在运行？）');
+  return null;
+}
+
+/**
+ * 把发现到的基址写回 config.json（保留其它字段与原文件的 2 空格缩进）。
+ * @param {string} configFile - config.json 的绝对路径
+ * @param {string} baseUrl - 新基址
+ * @returns {boolean} 是否真的改写了文件
+ */
+export function persistDshBaseUrl(configFile, baseUrl) {
+  try {
+    const raw = fs.readFileSync(configFile, 'utf8');
+    const cfg = JSON.parse(raw);
+    if (!cfg.dsh || typeof cfg.dsh !== 'object') return false;
+    if (cfg.dsh.baseUrl === baseUrl) return false;
+    cfg.dsh.baseUrl = baseUrl;
+    fs.writeFileSync(configFile, `${JSON.stringify(cfg, null, 2)}\n`, 'utf8');
+    return true;
+  } catch {
+    return false;
+  }
+}
+
+export { path };
+
```

