### 2.3 脚本一：复现静默失效

`reproduce-web-search.mjs` —— 通过 MCP 协议 spawn 自带的 server，调用其 `web_search` 工具：

```javascript
// reproduce-web-search.mjs
// 通过 MCP 协议调用仓库自带的 web_search 工具，复现「静默失效」。
// 不仿写仓库逻辑：真实 spawn src/mcp-web-search-safe.js，
// 用 MCP 客户端连接并调用它暴露的 web_search 工具。
//
// 用法：node reproduce-web-search.mjs [轮数] [--json]
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SERVER = path.join(__dirname, 'src', 'mcp-web-search-safe.js');

const ROUNDS = Number(process.argv[2] || 10);
const AS_JSON = process.argv.includes('--json');
const PAUSE_MS = 800;
const QUERIES = ['明日方舟 罗德岛', '明日方舟 普瑞赛斯', '泰拉 源石'];

async function callTool(client, query) {
  const t0 = Date.now();
  const res = await client.callTool({ name: 'web_search', arguments: { query } });
  const ms = Date.now() - t0;

  let parsed = 0, raw = '';
  for (const c of res.content || []) if (c.type === 'text') raw += c.text;
  try {
    const obj = JSON.parse(raw);
    parsed = Array.isArray(obj.results) ? obj.results.length : -1;
  } catch { parsed = -1; }
  return { parsed, isError: !!res.isError, ms };
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  console.log('='.repeat(78));
  console.log('web_search 静默失效复现 —— 经由仓库自带 MCP 工具');
  console.log('='.repeat(78));
  console.log(`server : ${SERVER}`);
  console.log(`采样: ${ROUNDS * QUERIES.length} 次\n`);

  const client = new Client({ name: 'repro-client', version: '1.0.0' });
  await client.connect(new StdioClientTransport({
    command: process.execPath, args: [SERVER], stderr: 'pipe',
  }));

  const tools = await client.listTools();
  console.log('工具列表:', tools.tools.map((t) => t.name).join(', '), '\n');

  const rows = [];
  try {
    for (let r = 1; r <= ROUNDS; r++) {
      for (const q of QUERIES) {
        try {
          const out = await callTool(client, q);
          rows.push({ round: r, query: q, ...out });
          console.log(`  r${String(r).padEnd(2)} ${q.padEnd(16)} results=${String(out.parsed).padEnd(3)} isError=${String(out.isError).padEnd(5)} ${out.ms}ms`);
        } catch (e) {
          rows.push({ round: r, query: q, parsed: -1, error: String(e?.message ?? e) });
          console.log(`  r${String(r).padEnd(2)} ${q.padEnd(16)} EXCEPTION ${e?.message ?? e}`);
        }
      }
      await sleep(PAUSE_MS);
    }
  } finally { await client.close().catch(() => {}); }

  const vals = rows.map((x) => x.parsed);
  const ok = vals.filter((v) => v > 0).length;
  const rate = vals.length ? (ok / vals.length) * 100 : 0;
  const silentFail = rows.filter((x) => x.parsed === 0 && !x.isError).length;

  console.log('\n' + '='.repeat(78));
  console.log('汇总');
  console.log('='.repeat(78));
  console.log(`总调用     : ${rows.length}`);
  console.log(`返回非空   : ${ok}  (${rate.toFixed(1)}%)`);
  console.log(`返回空数组 : ${rows.filter((x) => x.parsed === 0).length}`);
  console.log(`其中 isError=false（静默）: ${silentFail}`);
  console.log(`真实抛错   : ${rows.filter((x) => x.isError).length}`);

  console.log('\n逐查询结果:');
  for (const q of QUERIES) {
    console.log(`  ${q.padEnd(16)} ${JSON.stringify(rows.filter((x) => x.query === q).map((x) => x.parsed))}`);
  }

  console.log('\n结论:');
  if (rate < 100) {
    console.log(`  复现成功：${(100 - rate).toFixed(1)}% 的调用返回空数组，`);
    console.log('  且 isError 均为 false —— agent 无法感知失败，只会误以为「搜不到」。');
  } else {
    console.log('  本轮未复现（全部返回非空）。可能与网络/节点有关，建议稍后重试。');
  }

  if (AS_JSON) {
    const fs = await import('node:fs');
    fs.writeFileSync('repro-web-search.json', JSON.stringify({ rounds: ROUNDS, rows, rate }, null, 2), 'utf8');
    console.log('\nJSON: repro-web-search.json');
  }
}

main().catch((e) => { console.error('FAILED:', e?.message ?? e); process.exit(1); });
```

